import sys
import os
import json
import re
from decimal import Decimal


def normalize_date(val):
    if not val or not isinstance(val, str):
        return None
    val = val.strip()
    m = re.match(r"^(\d{4}-\d{2}-\d{2})", val)
    if m:
        return m.group(1)
    return None


def normalize_amount(val):
    if val is None:
        return None
    try:
        # Convert to string first to avoid binary float artifacts where possible
        s = str(val).strip()
        # Verify it can parse as Decimal
        d = Decimal(s)
        return (d, s)
    except Exception:
        return None


def extract_fact_value(award, fact_name):
    if fact_name == "performance start":
        pop = award.get("period_of_performance") or {}
        raw = pop.get("start_date")
        norm = normalize_date(raw)
        return norm, norm
    elif fact_name == "performance end":
        pop = award.get("period_of_performance") or {}
        raw = pop.get("end_date")
        norm = normalize_date(raw)
        return norm, norm
    elif fact_name == "amount obligated":
        raw = award.get("total_obligation")
        norm = normalize_amount(raw)
        if norm is not None:
            return norm[0], norm[1]
        return None, None
    elif fact_name == "potential value":
        raw = award.get("base_and_all_options")
        norm = normalize_amount(raw)
        if norm is not None:
            return norm[0], norm[1]
        return None, None
    return None, None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards = []
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards = json.load(f)

    # Index awards by generated_unique_award_id
    awards_by_id = {}
    for award in awards:
        award_id = award.get("generated_unique_award_id")
        if award_id:
            awards_by_id.setdefault(award_id, []).append(award)

    doc_name = "usaspending_awards"
    results = {}
    rule_facts_map = manifest.get("facts", {})

    for pair in manifest.get("pairs", []):
        parts = pair.split("::", 1)
        if len(parts) != 2:
            continue
        rule_id, entity_id = parts[0], parts[1]
        facts = rule_facts_map.get(rule_id, [])

        matching_awards = awards_by_id.get(entity_id, [])
        pair_result = {}

        for fact in facts:
            if not matching_awards:
                pair_result[fact] = "ABSENT"
                continue

            values = []
            for award in matching_awards:
                norm_key, display_val = extract_fact_value(award, fact)
                if norm_key is not None:
                    values.append((norm_key, display_val))

            if not values:
                pair_result[fact] = "ABSENT"
            else:
                # Check for conflict among present values
                first_norm_key = values[0][0]
                has_conflict = any(v[0] != first_norm_key for v in values)
                if has_conflict:
                    pair_result[fact] = "CONFLICT"
                else:
                    pair_result[fact] = [values[0][1], doc_name]

        results[pair] = pair_result

    print(json.dumps(results, indent=2))


if __name__ == "__main__":
    main()

