import sys
import os
import json
from decimal import Decimal


def get_field_value(record, path):
    curr = record
    for part in path.split("."):
        if isinstance(curr, dict):
            curr = curr.get(part)
        else:
            return None
    return curr


def resolve_fact(records, path, doc_name):
    values = []
    for r in records:
        v = get_field_value(r, path)
        if v is not None and v != "":
            values.append(v)

    if not values:
        return "ABSENT"

    # Check for conflict
    first = values[0]
    for other in values[1:]:
        if isinstance(first, Decimal) and isinstance(other, Decimal):
            if first != other:
                return "CONFLICT"
        else:
            if str(first) != str(other):
                return "CONFLICT"

    return [str(first), doc_name]


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load usaspending_awards if available
    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    awards_by_id = {}
    if os.path.exists(awards_path):
        with open(awards_path, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)
            if isinstance(awards_data, list):
                for item in awards_data:
                    award_id = item.get("generated_unique_award_id")
                    if award_id:
                        awards_by_id.setdefault(award_id, []).append(item)

    # Rules definition mapping (rule_id, fact_name) -> (doc_name, field_path)
    rule_fact_specs = {
        ("usa.period_3y", "performance start"): ("usaspending_awards", "period_of_performance.start_date"),
        ("usa.period_3y", "performance end"): ("usaspending_awards", "period_of_performance.end_date"),
        ("usa.obligated_95", "amount obligated"): ("usaspending_awards", "total_obligation"),
        ("usa.obligated_95", "potential value"): ("usaspending_awards", "base_and_all_options"),
    }

    pairs = manifest.get("pairs", [])
    facts_manifest = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        output[pair] = {}

        rule_facts = facts_manifest.get(rule_id, [])
        for fact_name in rule_facts:
            spec = rule_fact_specs.get((rule_id, fact_name))
            if not spec:
                output[pair][fact_name] = "ABSENT"
                continue

            doc_name, field_path = spec
            if doc_name == "usaspending_awards":
                records = awards_by_id.get(entity, [])
                output[pair][fact_name] = resolve_fact(records, field_path, doc_name)
            else:
                output[pair][fact_name] = "ABSENT"

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

