import sys
import os
import json
import re
from decimal import Decimal


def get_field(obj, path):
    parts = path.split(".")
    curr = obj
    for p in parts:
        if isinstance(curr, dict):
            curr = curr.get(p)
        else:
            return None
    return curr


def get_field_info(rule_id, fact_name):
    rule_fact_field = {
        "usa.period_3y": {
            "performance start": ("period_of_performance.start_date", "date"),
            "performance end": ("period_of_performance.end_date", "date"),
        },
        "usa.obligated_95": {
            "amount obligated": ("total_obligation", "amount"),
            "potential value": ("base_and_all_options", "amount"),
        },
    }
    if rule_id in rule_fact_field and fact_name in rule_fact_field[rule_id]:
        return rule_fact_field[rule_id][fact_name]

    fn_lower = fact_name.lower()
    if "start" in fn_lower:
        return ("period_of_performance.start_date", "date")
    if "end" in fn_lower:
        return ("period_of_performance.end_date", "date")
    if "obligat" in fn_lower:
        return ("total_obligation", "amount")
    if "potential" in fn_lower or "base" in fn_lower:
        return ("base_and_all_options", "amount")
    return None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    target_doc = "usaspending_awards"
    doc_file = None
    if os.path.isdir(packet_dir):
        for fname in os.listdir(packet_dir):
            name, ext = os.path.splitext(fname)
            if name == target_doc and ext.lower() in [".json", ""]:
                doc_file = os.path.join(packet_dir, fname)
                break

    awards_list = []
    if doc_file and os.path.exists(doc_file):
        with open(doc_file, "r", encoding="utf-8") as f:
            try:
                data = json.load(f, parse_float=Decimal, parse_int=Decimal)
                if isinstance(data, list):
                    awards_list = data
                elif isinstance(data, dict):
                    awards_list = data.get("results", data.get("awards", [data]))
            except Exception:
                awards_list = []

    awards_by_id = {}
    for award in awards_list:
        if not isinstance(award, dict):
            continue
        keys = []
        if award.get("generated_unique_award_id"):
            keys.append(str(award["generated_unique_award_id"]))
        if award.get("id") is not None:
            keys.append(str(award["id"]))
        for k in keys:
            awards_by_id.setdefault(k, []).append(award)

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity_id = pair.split("::", 1)
        else:
            rule_id, entity_id = pair, ""

        fact_names = facts_by_rule.get(rule_id, [])
        pair_result = {}

        matching_records = awards_by_id.get(entity_id, [])

        for fact_name in fact_names:
            field_info = get_field_info(rule_id, fact_name)
            if not field_info:
                pair_result[fact_name] = "ABSENT"
                continue

            field_path, val_type = field_info

            extracted_vals = []
            for rec in matching_records:
                v = get_field(rec, field_path)
                if v is None or v == "":
                    continue
                extracted_vals.append(v)

            if not extracted_vals:
                pair_result[fact_name] = "ABSENT"
            else:
                if val_type == "amount":
                    try:
                        dec_vals = [Decimal(str(x)) for x in extracted_vals]
                        if any(d != dec_vals[0] for d in dec_vals):
                            pair_result[fact_name] = "CONFLICT"
                        else:
                            pair_result[fact_name] = [f"{dec_vals[0]:f}", target_doc]
                    except Exception:
                        if any(x != extracted_vals[0] for x in extracted_vals):
                            pair_result[fact_name] = "CONFLICT"
                        else:
                            pair_result[fact_name] = [str(extracted_vals[0]), target_doc]
                elif val_type == "date":
                    formatted_dates = []
                    for d in extracted_vals:
                        s = str(d).strip()
                        m = re.match(r"^\d{4}-\d{2}-\d{2}", s)
                        if m:
                            formatted_dates.append(m.group(0))
                        else:
                            formatted_dates.append(s)
                    if any(fd != formatted_dates[0] for fd in formatted_dates):
                        pair_result[fact_name] = "CONFLICT"
                    else:
                        pair_result[fact_name] = [formatted_dates[0], target_doc]
                else:
                    str_vals = [str(x) for x in extracted_vals]
                    if any(sv != str_vals[0] for sv in str_vals):
                        pair_result[fact_name] = "CONFLICT"
                    else:
                        pair_result[fact_name] = [str_vals[0], target_doc]

        output[pair] = pair_result

    print(json.dumps(output, indent=1))


if __name__ == "__main__":
    main()

