import sys
import os
import json
import re
from decimal import Decimal


def get_nested(d, keys):
    curr = d
    for k in keys:
        if not isinstance(curr, dict):
            return None
        curr = curr.get(k)
    return curr


def format_value(val, val_type):
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.lower() == "null":
        return None
    if val_type == "date":
        m = re.match(r"^(\d{4}-\d{2}-\d{2})", s)
        if m:
            return m.group(1)
        return s
    elif val_type == "amount":
        try:
            # Normalize via Decimal for consistent string formatting
            d = Decimal(s)
            return s
        except Exception:
            return s
    return s


def values_conflict(v1, v2, val_type):
    if val_type == "amount":
        try:
            return Decimal(v1) != Decimal(v2)
        except Exception:
            return v1 != v2
    return v1 != v2


FACT_RULES = {
    "performance start": {
        "doc": "usaspending_awards",
        "extractor": lambda r: get_nested(r, ["period_of_performance", "start_date"]),
        "type": "date",
    },
    "performance end": {
        "doc": "usaspending_awards",
        "extractor": lambda r: get_nested(r, ["period_of_performance", "end_date"]),
        "type": "date",
    },
    "amount obligated": {
        "doc": "usaspending_awards",
        "extractor": lambda r: r.get("total_obligation"),
        "type": "amount",
    },
    "potential value": {
        "doc": "usaspending_awards",
        "extractor": lambda r: r.get("base_and_all_options"),
        "type": "amount",
    },
}


def load_awards(packet_dir):
    awards_by_id = {}
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            data = json.load(f, parse_float=Decimal, parse_int=Decimal)
            if isinstance(data, list):
                for item in data:
                    award_id = item.get("generated_unique_award_id")
                    if award_id:
                        awards_by_id.setdefault(award_id, []).append(item)
    return awards_by_id


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    awards_by_id = load_awards(packet_dir)

    results = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        target_facts = facts_spec.get(rule_id, [])

        pair_result = {}
        for fact_name in target_facts:
            rule_info = FACT_RULES.get(fact_name)
            if not rule_info:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name = rule_info["doc"]
            records = awards_by_id.get(entity, [])

            extracted_values = []
            for rec in records:
                raw_val = rule_info["extractor"](rec)
                formatted = format_value(raw_val, rule_info["type"])
                if formatted is not None:
                    extracted_values.append(formatted)

            if not extracted_values:
                pair_result[fact_name] = "ABSENT"
            else:
                has_conflict = False
                first_val = extracted_values[0]
                for v in extracted_values[1:]:
                    if values_conflict(first_val, v, rule_info["type"]):
                        has_conflict = True
                        break

                if has_conflict:
                    pair_result[fact_name] = "CONFLICT"
                else:
                    pair_result[fact_name] = [first_val, doc_name]

        results[pair] = pair_result

    print(json.dumps(results, indent=1))


if __name__ == "__main__":
    main()

