import os
import json
import re
from decimal import Decimal


def normalize_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    match = re.search(r'\b(\d{4}-\d{2}-\d{2})\b', val_str)
    if match:
        return match.group(1)
    return None


def normalize_amount(val):
