        return None
    val_str = str(val).strip().replace('$', '').replace(',', '')
    if not val_str:
        return None
    try:
        d = Decimal(val_str)
        s = val_str
        if 'e' in s.lower():
            s = f"{d:f}"
        return (d, s)
    except Exception:
        return None


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, 'usaspending_awards.json')
    awards_by_id = {}
    if os.path.exists(awards_file):
        with open(awards_file, 'r', encoding='utf-8') as f:
            data = json.load(f, parse_float=str, parse_int=str)
            if isinstance(data, dict):
                data = data.get('results', [data])
            if isinstance(data, list):
                for item in data:
                    award_id = item.get('generated_unique_award_id')
                    if award_id:
                        awards_by_id.setdefault(award_id, []).append(item)

    doc_name = 'usaspending_awards'
    pairs = manifest.get('pairs', [])
    facts_schema = manifest.get('facts', {})

    result = {}

    for pair in pairs:
        if '::' not in pair:
            continue
        rule_id, entity_id = pair.split('::', 1)
        rule_facts = facts_schema.get(rule_id, [])

        records = awards_by_id.get(entity_id, [])
        pair_res = {}

        for fact in rule_facts:
            if fact == 'performance start':
                extracted = []
                for rec in records:
                    pop = rec.get('period_of_performance') or {}
                    raw_val = pop.get('start_date')
                    norm = normalize_date(raw_val)
                    if norm is not None:
                        extracted.append(norm)

                if not extracted:
                    pair_res[fact] = "ABSENT"
                elif any(v != extracted[0] for v in extracted):
                    pair_res[fact] = "CONFLICT"
                else:
                    pair_res[fact] = [extracted[0], doc_name]

            elif fact == 'performance end':
                extracted = []
                for rec in records:
                    pop = rec.get('period_of_performance') or {}
                    raw_val = pop.get('end_date')
                    norm = normalize_date(raw_val)
                    if norm is not None:
                        extracted.append(norm)

                if not extracted:
                    pair_res[fact] = "ABSENT"
                elif any(v != extracted[0] for v in extracted):
                    pair_res[fact] = "CONFLICT"
                else:
                    pair_res[fact] = [extracted[0], doc_name]

            elif fact == 'amount obligated':
                extracted = []
                for rec in records:
                    raw_val = rec.get('total_obligation')
                    norm = normalize_amount(raw_val)
                    if norm is not None:
                        extracted.append(norm)

                if not extracted:
                    pair_res[fact] = "ABSENT"
                elif any(v[0] != extracted[0][0] for v in extracted):
                    pair_res[fact] = "CONFLICT"
                else:
                    pair_res[fact] = [extracted[0][1], doc_name]

            elif fact == 'potential value':
                extracted = []
                for rec in records:
                    raw_val = rec.get('base_and_all_options')
                    norm = normalize_amount(raw_val)
                    if norm is not None:
                        extracted.append(norm)

                if not extracted:
                    pair_res[fact] = "ABSENT"
                elif any(v[0] != extracted[0][0] for v in extracted):
                    pair_res[fact] = "CONFLICT"
                else:
                    pair_res[fact] = [extracted[0][1], doc_name]

            else:
                pair_res[fact] = "ABSENT"

        result[pair] = pair_res

    print(json.dumps(result, indent=1))


if __name__ == '__main__':
    main()

